'use client';

import React, { useState } from 'react';
import {
    User, Lock, Link as LinkIcon, Copy, Check, Sparkles, Wand2,
    Settings2, RefreshCw, Eye, EyeOff
} from 'lucide-react';
import { haptic } from '@lembaran/core/Indera';

interface KredensialData {
    username?: string;
    password?: string;
    url?: string;
}

interface PenyusunKredensialProps {
    data: KredensialData;
    onChange: (data: KredensialData) => void;
}

export const PenyusunKredensial = ({ data, onChange }: PenyusunKredensialProps) => {
    const [showPassword, setShowPassword] = useState(false);
    const [copiedField, setCopiedField] = useState<string | null>(null);
    const [isPasting, setIsPasting] = useState(false);
    const [showPassGen, setShowPassGen] = useState(false);
    const [genLength, setGenLength] = useState(16);

    const getPasswordStrength = (p: string) => {
        if (!p) return 0;
        let score = 0;
        if (p.length > 8) score++;
        if (p.length > 12) score++;
        if (/[A-Z]/.test(p)) score++;
        if (/[0-9]/.test(p)) score++;
        if (/[^A-Za-z0-9]/.test(p)) score++;
        return score;
    };
    const strength = getPasswordStrength(data.password || "");

    const updateField = (field: keyof KredensialData, value: string) => {
        onChange({ ...data, [field]: value });
    };

    const handleCopy = (text: string | undefined, field: string) => {
        if (!text) return;
        navigator.clipboard.writeText(text);
        setCopiedField(field);
        haptic.success();
        setTimeout(() => setCopiedField(null), 2000);
    };

    const generatePassword = () => {
        const chars = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789!@#$%^&*()_+";
        const randomValues = new Uint32Array(genLength);
        window.crypto.getRandomValues(randomValues);
        let result = "";
        for (let i = 0; i < genLength; i++) {
            result += chars.charAt(randomValues[i] % chars.length);
        }
        updateField('password', result);
        setShowPassword(true);
        haptic.medium();
    };

    const handleSmartPaste = async () => {
        setIsPasting(true);
        haptic.medium();
        try {
            const text = await navigator.clipboard.readText();
            if (!text) return;

            const newData: KredensialData = { ...data };
            const userMatch = text.match(/(?:username|user|email|id|pengguna):\s*([^\n\r,]+)/i);
            const passMatch = text.match(/(?:password|pass|sandi|pwd):\s*([^\n\r,]+)/i);
            const urlMatch = text.match(/(?:url|link|site|tautan):\s*([^\n\r\s,]+)/i);

            if (userMatch) newData.username = userMatch[1].trim();
            if (passMatch) newData.password = passMatch[1].trim();
            if (urlMatch) newData.url = urlMatch[1].trim();

            onChange(newData);
            haptic.success();
        } catch (err) {} finally {
            setTimeout(() => setIsPasting(false), 500);
        }
    };

    const inputClass = "flex-1 bg-transparent border-none focus:outline-none text-[13px] sm:text-[14px] py-1 placeholder:opacity-30 min-w-0";

    return (
        <div className="space-y-2 mb-3 w-full animate-in fade-in slide-in-from-top-2 duration-300">
            <div className="flex items-center justify-between px-1">
                <span className="text-[10px] font-bold uppercase tracking-wider text-[var(--text-secondary)] opacity-50 flex items-center gap-1.5">
                    <Sparkles size={10} /> Kredensial
                </span>
                <div className="flex items-center gap-2">
                    <button
                        onClick={() => setShowPassGen(!showPassGen)}
                        className={`flex items-center gap-1 text-[10px] font-bold px-2.5 py-1 rounded-full border ${showPassGen ? 'bg-blue-500 text-white border-blue-500' : 'border-blue-500/20 text-blue-500 hover:bg-blue-500/5'} transition-all`}
                    >
                        <Settings2 size={10} /> Pembangkit
                    </button>
                    <button
                        onClick={handleSmartPaste}
                        className={`flex items-center gap-1 text-[10px] font-bold px-2.5 py-1 rounded-full border border-blue-500/20 text-blue-500 hover:bg-blue-500/5 transition-all ${isPasting ? 'animate-pulse' : ''}`}
                    >
                        <Wand2 size={10} /> Tempel Pintar
                    </button>
                </div>
            </div>

            {showPassGen && (
                <div className="mx-1 p-3 bg-blue-500/5 border border-blue-500/10 rounded-2xl flex items-center justify-between gap-4 animate-in zoom-in-95 duration-200">
                    <div className="flex flex-col gap-1 flex-1">
                        <span className="text-[9px] font-black uppercase text-blue-500/60">Panjang: {genLength}</span>
                        <input
                            type="range" min="8" max="32" value={genLength}
                            onChange={(e) => setGenLength(parseInt(e.target.value))}
                            className="w-full h-1 bg-blue-500/20 rounded-lg appearance-none cursor-pointer accent-blue-500"
                        />
                    </div>
                    <button onClick={generatePassword} className="px-4 py-2 bg-blue-500 text-white rounded-xl text-[11px] font-bold shadow-lg active:scale-95 transition-transform flex items-center gap-2">
                        <RefreshCw size={12} /> Acak
                    </button>
                </div>
            )}

            <div className="ios-list-group border border-[var(--separator)]/20 shadow-sm overflow-hidden w-full mb-0">
                <div className="flex items-center px-3 gap-2 group">
                    <User size={15} className="text-blue-500 opacity-40 group-focus-within:opacity-100 transition-opacity" />
                    <input type="text" value={data.username || ''} onChange={(e) => updateField('username', e.target.value)} placeholder="Username / Email" className={inputClass} />
                    <button onClick={() => handleCopy(data.username, 'user')} className="p-1.5 opacity-20 hover:opacity-100 transition-opacity text-blue-500">{copiedField === 'user' ? <Check size={14} /> : <Copy size={14} />}</button>
                </div>
                <div className="ios-separator"></div>

                <div className="flex flex-col">
                    <div className="flex items-center px-3 gap-2 group">
                        <Lock size={15} className="text-blue-500 opacity-40 group-focus-within:opacity-100 transition-opacity" />
                        <input type={showPassword ? "text" : "password"} value={data.password || ''} onChange={(e) => updateField('password', e.target.value)} placeholder="Password" className={inputClass} />
                        <button onClick={() => setShowPassword(!showPassword)} className="p-1.5 opacity-20 hover:opacity-100 transition-opacity">{showPassword ? <EyeOff size={14} /> : <Eye size={14} />}</button>
                        <button onClick={() => handleCopy(data.password, 'pass')} className="p-1.5 opacity-20 hover:opacity-100 transition-opacity text-blue-500">{copiedField === 'pass' ? <Check size={14} /> : <Copy size={14} />}</button>
                    </div>
                    {data.password && (
                        <div className="px-10 pb-2 flex gap-1">
                            {[1, 2, 3, 4, 5].map((i) => (
                                <div key={i} className={`h-0.5 flex-1 rounded-full transition-colors ${i <= strength ? (strength <= 2 ? "bg-red-500" : strength <= 4 ? "bg-yellow-500" : "bg-green-500") : "bg-white/5"}`} />
                            ))}
                        </div>
                    )}
                </div>
                <div className="ios-separator"></div>

                <div className="flex items-center px-3 gap-2 group">
                    <LinkIcon size={15} className="text-blue-500 opacity-40 group-focus-within:opacity-100 transition-opacity" />
                    <input type="text" value={data.url || ''} onChange={(e) => updateField('url', e.target.value)} placeholder="URL" className={inputClass} />
                    <button onClick={() => handleCopy(data.url, 'url')} className="p-1.5 opacity-20 hover:opacity-100 transition-opacity text-blue-500">{copiedField === 'url' ? <Check size={14} /> : <Copy size={14} />}</button>
                </div>
            </div>
        </div>
    );
};

'use client';

import { useEditor, EditorContent } from '@tiptap/react';
import { BubbleMenu, FloatingMenu } from '@tiptap/react/menus';
import StarterKit from '@tiptap/starter-kit';
import Placeholder from '@tiptap/extension-placeholder';
import CodeBlockLowlight from '@tiptap/extension-code-block-lowlight';
import { common, createLowlight } from 'lowlight';
import { PerintahGarisMiring, PerintahGarisMiringConfig } from './PerintahGarisMiring';
import { EkstensiTanggalCerdas } from './EkstensiTanggalCerdas';
import React, { useState } from 'react';
import {
    Bold, Italic, Heading1, List, Terminal, Sparkles, Loader2, Command
} from 'lucide-react';
import { Pujangga } from '@lembaran/core/Pujangga';
import { haptic } from '@lembaran/core/Indera';
import { usePundi } from '@lembaran/core/Pundi';

import 'highlight.js/styles/github-dark.css';

const lowlight = createLowlight(common);

interface PenyusunCatatanProps {
    content: string;
    onChange: (content: string) => void;
    editable?: boolean;
    placeholder?: string;
}

export const PenyusunCatatan = ({
    content,
    onChange,
    editable = true,
    placeholder = 'Mulai menulis kisah Anda...'
}: PenyusunCatatanProps) => {
    const { settings } = usePundi();
    const [isMonospace, setIsMonospace] = useState(false);
    const [isSummarizing, setIsSummarizing] = useState(false);
    const [vimMode, setVimMode] = useState('INSERT');

    const editor = useEditor({
        extensions: [
            StarterKit.configure({
                heading: { levels: [1, 2] },
                codeBlock: false,
            }),
            CodeBlockLowlight.configure({ lowlight }),
            Placeholder.configure({ placeholder }),
            PerintahGarisMiring.configure(PerintahGarisMiringConfig),
            EkstensiTanggalCerdas,
        ],
        content: content,
        editable: editable,
        onUpdate: ({ editor }) => {
            onChange(editor.getHTML());
        },
        editorProps: {
            attributes: {
                class: `prose prose-sm sm:prose-base lg:prose-lg xl:prose-2xl dark:prose-invert my-4 px-1 focus:outline-none min-h-[calc(100vh-300px)] text-[var(--text-primary)] ${isMonospace ? 'font-mono' : 'font-sans'}`,
            },
            handleKeyDown: (view, event) => {
                if (!settings.vimMode) return false;

                if (event.key === 'Escape') {
                    setVimMode('NORMAL');
                    haptic.light();
                    return true;
                }

                if (vimMode === 'NORMAL') {
                    if (event.key === 'i') {
                        setVimMode('INSERT');
                        return true;
                    }

                    const selection = window.getSelection();
                    if (!selection) return true;

                    // Navigation
                    if (event.key === 'h') { selection.modify('move', 'backward', 'character'); return true; }
                    if (event.key === 'l') { selection.modify('move', 'forward', 'character'); return true; }
                    if (event.key === 'j') { selection.modify('move', 'forward', 'line'); return true; }
                    if (event.key === 'k') { selection.modify('move', 'backward', 'line'); return true; }

                    // Basic Vim Operations
                    if (event.key === 'x') {
                        // Delete current character
                        editor?.chain().focus().deleteRange({ from: view.state.selection.from, to: view.state.selection.from + 1 }).run();
                        return true;
                    }
                    if (event.key === 'w') { selection.modify('move', 'forward', 'word'); return true; }
                    if (event.key === 'b') { selection.modify('move', 'backward', 'word'); return true; }
                    if (event.key === '0') { selection.modify('move', 'backward', 'lineboundary'); return true; }
                    if (event.key === '$') { selection.modify('move', 'forward', 'lineboundary'); return true; }
                    if (event.key === 'G') { selection.modify('move', 'forward', 'documentboundary'); return true; }
                    if (event.key === 'g' && event.shiftKey === false) {
                        // Simplified gg
                        selection.modify('move', 'backward', 'documentboundary'); return true;
                    }

                    return true;
                }
                return false;
            }
        },
        immediatelyRender: false,
    });

    const handleAISummary = async () => {
        if (!editor || isSummarizing) return;
        setIsSummarizing(true);
        haptic.medium();
        try {
            const summary = await Pujangga.ringkasCerdas(editor.getHTML());
            editor.chain().focus().insertContent(`<p><strong>${summary}</strong></p>`).run();
            haptic.success();
        } catch (err) {
            haptic.error();
        } finally {
            setIsSummarizing(false);
        }
    };

    if (!editor) return null;

    return (
        <div className="relative w-full h-full">
            {editable && (
                <div className="absolute top-[-45px] right-0 flex items-center gap-2 z-10">
                    {settings.vimMode && (
                        <div className={`px-2 py-1 rounded-md border transition-all ${vimMode === 'NORMAL' ? 'bg-orange-500 text-white border-orange-600' : 'bg-orange-500/10 border-orange-500/20 text-orange-500'} text-[9px] font-black tracking-widest flex items-center gap-2`}>
                            <Command size={10} />
                            VIM: {vimMode}
                        </div>
                    )}
                    <button onClick={() => setIsMonospace(!isMonospace)} className={`p-1.5 rounded-md border transition-all ${isMonospace ? 'bg-blue-500/10 border-blue-500/30 text-blue-500' : 'bg-[var(--surface)] border-[var(--separator)]/30 text-[var(--text-secondary)] opacity-40 hover:opacity-100'}`} title="Tampilan Monospace"><Terminal size={16} /></button>
                    <button onClick={handleAISummary} disabled={isSummarizing} className={`p-1.5 rounded-md border transition-all ${isSummarizing ? 'bg-purple-500/10 text-purple-500 border-purple-500/30' : 'bg-[var(--surface)] border-[var(--separator)]/30 text-purple-500 opacity-40 hover:opacity-100'}`} title="Ringkas Catatan (AI)">{isSummarizing ? <Loader2 size={16} className="animate-spin" /> : <Sparkles size={16} />}</button>
                </div>
            )}

            <BubbleMenu editor={editor} className="flex items-center gap-1 p-1 rounded-xl bg-[var(--background)] border border-[var(--separator)] shadow-lg backdrop-blur-md">
                <button onClick={() => editor.chain().focus().toggleBold().run()} className={`p-2 rounded-lg hover:bg-[var(--glass-bg)] transition-colors ${editor.isActive('bold') ? 'text-[var(--primary)] bg-[var(--primary)]/10' : 'text-[var(--text-secondary)]'}`}><Bold size={16} /></button>
                <button onClick={() => editor.chain().focus().toggleItalic().run()} className={`p-2 rounded-lg hover:bg-[var(--glass-bg)] transition-colors ${editor.isActive('italic') ? 'text-[var(--primary)] bg-[var(--primary)]/10' : 'text-[var(--text-secondary)]'}`}><Italic size={16} /></button>
            </BubbleMenu>

            <FloatingMenu editor={editor} className="flex items-center gap-1 p-1 rounded-xl bg-[var(--background)] border border-[var(--separator)] shadow-lg backdrop-blur-md">
                <button onClick={() => editor.chain().focus().toggleHeading({ level: 1 }).run()} className={`p-2 rounded-lg hover:bg-[var(--glass-bg)] transition-colors ${editor.isActive('heading', { level: 1 }) ? 'text-[var(--primary)] bg-[var(--primary)]/10' : 'text-[var(--text-secondary)]'}`}><Heading1 size={16} /></button>
                <button onClick={() => editor.chain().focus().toggleBulletList().run()} className={`p-2 rounded-lg hover:bg-[var(--glass-bg)] transition-colors ${editor.isActive('bulletList') ? 'text-[var(--primary)] bg-[var(--primary)]/10' : 'text-[var(--text-secondary)]'}`}><List size={16} /></button>
                <button onClick={handleAISummary} className="p-2 rounded-lg hover:bg-[var(--glass-bg)] text-purple-500"><Sparkles size={16} /></button>
            </FloatingMenu>

            <EditorContent editor={editor} className="min-h-full pb-20 editor-instance" />
        </div>
    );
};

'use client';

import React, { useEffect, useState } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { Arsip } from '@lembaran/core/Arsip';
import { Note } from '@lembaran/core/Rumus';
import { X, Maximize2, Minimize2, ZoomIn, ZoomOut, RefreshCw } from 'lucide-react';
import { haptic } from '@lembaran/core/Indera';

interface Node extends Note {
    x: number;
    y: number;
    vx: number;
    vy: number;
}

export const PetaCatatan = ({ onClose }: { onClose: () => void }) => {
    const [nodes, setNodes] = useState<Node[]>([]);
    const [links, setLinks] = useState<{ source: number, target: number }[]>([]);
    const [isFullScreen, setIsFullScreen] = useState(false);
    const [zoom, setZoom] = useState(1);

    const loadGraph = async () => {
        haptic.light();
        const allNotes = await Arsip.getAllNotes();
        const graphNodes: Node[] = allNotes.map((note) => ({
            ...note,
            x: 400 + (Math.random() - 0.5) * 500,
            y: 300 + (Math.random() - 0.5) * 400,
            vx: 0,
            vy: 0
        }));

        const graphLinks: { source: number, target: number }[] = [];
        for (let i = 0; i < graphNodes.length; i++) {
            for (let j = i + 1; j < graphNodes.length; j++) {
                const sharedTags = graphNodes[i].tags.filter(tag => graphNodes[j].tags.includes(tag));
                if (sharedTags.length > 0) {
                    graphLinks.push({ source: i, target: j });
                }
            }
        }

        setNodes(graphNodes);
        setLinks(graphLinks);
    };

    useEffect(() => {
        loadGraph();
    }, []);

    return (
        <motion.div
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            className={`fixed inset-0 z-[200] bg-[var(--background)]/90 backdrop-blur-2xl flex flex-col ${isFullScreen ? 'p-0' : 'p-4 sm:p-10'}`}
        >
            <div className="flex justify-between items-center mb-6 px-6">
                <div className="flex flex-col">
                    <h2 className="text-3xl font-bold tracking-tighter">Peta Memori</h2>
                    <p className="text-[11px] text-[var(--text-muted)] font-black uppercase tracking-[0.2em]">Visualisasi Relasi Aksara</p>
                </div>
                <div className="flex gap-3">
                    <button onClick={() => setZoom(prev => Math.min(prev + 0.2, 2))} className="p-3 rounded-2xl bg-[var(--surface)] hover:bg-[var(--surface-active)] transition-colors"><ZoomIn size={20} /></button>
                    <button onClick={() => setZoom(prev => Math.max(prev - 0.2, 0.5))} className="p-3 rounded-2xl bg-[var(--surface)] hover:bg-[var(--surface-active)] transition-colors"><ZoomOut size={20} /></button>
                    <button onClick={loadGraph} className="p-3 rounded-2xl bg-[var(--surface)] hover:bg-[var(--surface-active)] transition-colors"><RefreshCw size={20} /></button>
                    <div className="w-px h-10 bg-[var(--separator)]/20 mx-2" />
                    <button onClick={onClose} className="p-3 rounded-2xl bg-red-500/10 text-red-500 hover:bg-red-500/20 transition-colors"><X size={20} /></button>
                </div>
            </div>

            <div className="flex-1 relative overflow-hidden bg-[var(--surface)]/20 rounded-[3rem] border border-[var(--separator)]/20 shadow-2xl">
                <motion.svg
                    animate={{ scale: zoom }}
                    className="w-full h-full cursor-grab active:cursor-grabbing"
                >
                    {links.map((link, i) => (
                        <line
                            key={i}
                            x1={nodes[link.source].x} y1={nodes[link.source].y}
                            x2={nodes[link.target].x} y2={nodes[link.target].y}
                            stroke="var(--primary)" strokeWidth="1.5" strokeOpacity="0.15"
                        />
                    ))}

                    {nodes.map((node, i) => (
                        <motion.g
                            key={node.id}
                            initial={{ scale: 0 }}
                            animate={{ scale: 1 }}
                            drag
                            dragMomentum={false}
                            onDrag={(e, info) => {
                                const newNodes = [...nodes];
                                newNodes[i].x += info.delta.x / zoom;
                                newNodes[i].y += info.delta.y / zoom;
                                setNodes(newNodes);
                            }}
                        >
                            <circle
                                cx={node.x} cy={node.y} r="8"
                                fill="var(--primary)"
                                className="filter drop-shadow-[0_0_8px_rgba(var(--primary-rgb),0.5)]"
                            />
                            <text
                                x={node.x} y={node.y + 25}
                                textAnchor="middle"
                                className="text-[10px] fill-[var(--text-primary)] font-bold tracking-tight pointer-events-none select-none"
                            >
                                {node.title}
                            </text>
                        </motion.g>
                    ))}
                </motion.svg>

                <div className="absolute bottom-10 left-10 p-6 rounded-[2rem] bg-[var(--background)]/40 backdrop-blur-md border border-white/5 shadow-2xl max-w-xs animate-in slide-in-from-bottom-10 duration-700">
                    <p className="text-[12px] text-[var(--text-secondary)] leading-relaxed italic">
                        &quot;Setiap aksara adalah simpul dalam jaring kesadaran. Hubungkan mereka melalui label untuk melihat pola pikir Anda secara visual.&quot;
                    </p>
                </div>
            </div>
        </motion.div>
    );
};

'use client';

import React, { useState } from 'react';
import { Terminal, Copy, Check } from 'lucide-react';
import { motion } from 'framer-motion';

const COMMANDS = {
    npm: 'npm install -g Abelion512/lembaran',
    yarn: 'yarn global add Abelion512/lembaran',
    bun: 'bun install -g Abelion512/lembaran',
};

export const CliInstallation = () => {
    const [method, setMethod] = useState<keyof typeof COMMANDS>('bun');
    const [copied, setCopied] = useState(false);

    const handleCopy = () => {
        navigator.clipboard.writeText(COMMANDS[method]);
        setCopied(true);
        setTimeout(() => setCopied(false), 2000);
    };

    return (
        <div className="hidden md:block max-w-2xl mx-auto px-6">
            <div className="glass-card overflow-hidden">
                <div className="px-4 py-3 bg-white/5 border-b border-white/5 flex items-center justify-between">
                    <div className="flex items-center gap-2">
                        <div className="flex gap-1.5">
                            <div className="w-3 h-3 rounded-full bg-red-500/50" />
                            <div className="w-3 h-3 rounded-full bg-yellow-500/50" />
                            <div className="w-3 h-3 rounded-full bg-green-500/50" />
                        </div>
                        <div className="ml-4 flex items-center gap-2 text-[10px] font-black uppercase tracking-widest text-gray-500">
                            <Terminal size={12} />
                            <span>Pasang via Terminal</span>
                        </div>
                    </div>
                    <div className="flex bg-black/20 p-1 rounded-lg">
                        {(['npm', 'yarn', 'bun'] as const).map((m) => (
                            <button
                                key={m}
                                onClick={() => setMethod(m)}
                                className={`px-3 py-1 text-[10px] font-bold rounded-md transition-all ${
                                    method === m ? 'bg-blue-500 text-white shadow-lg' : 'text-gray-500 hover:text-gray-300'
                                }`}
                            >
                                {m.toUpperCase()}
                            </button>
                        ))}
                    </div>
                </div>
                <div className="p-8 font-mono text-sm relative group">
                    <div className="flex items-center gap-4 text-gray-400">
                        <span className="text-blue-500 shrink-0 select-none">❯</span>
                        <code className="break-all">{COMMANDS[method]}</code>
                    </div>
                    <button
                        onClick={handleCopy}
                        className="absolute right-4 top-1/2 -translate-y-1/2 p-2 rounded-lg bg-white/5 border border-white/10 opacity-0 group-hover:opacity-100 transition-all hover:bg-white/10 active:scale-90"
                    >
                        {copied ? <Check size={16} className="text-green-500" /> : <Copy size={16} />}
                    </button>
                </div>
            </div>
            <div className="mt-4 flex items-center justify-center gap-6 text-[10px] font-black uppercase tracking-[0.2em] text-gray-500 opacity-50">
                <span>Ringan: ~2MB</span>
                <span className="w-1 h-1 rounded-full bg-gray-500" />
                <span>Instan: Shorthand Commands</span>
                <span className="w-1 h-1 rounded-full bg-gray-500" />
                <span>Aman: Sandboxed</span>
            </div>
        </div>
    );
};
